function main(input) {
    // 解析 JSON 字符串为数组
    let data1 = [];
    try {
        data1 = JSON.parse(input.data1);
    } catch (error) {
        console.error("Failed to parse JSON string:", error);
        return {
            result1: [],
            result2: [],
            result3: []
        };
    }

    // 确保 data1 是一个数组
    if (!Array.isArray(data1)) {
        console.error("Parsed data is not an array");
        return {
            result1: [],
            result2: [],
            result3: []
        };
    }

    // 按照 shiftDate 字段对输入数据进行分组
    let groupedData = data1.reduce((acc, item) => {
        if (!acc[item.shiftDate]) {
            acc[item.shiftDate] = [];
        }
        acc[item.shiftDate].push(item);
        return acc;
    }, {});

    // 将分组后的数据分别赋值给 result1 至 result6 变量
    let [result1, result2, result3] = Object.values(groupedData);

    return {
        result1: result1 || [],
        result2: result2 || [],
        result3: result3 || []
    };
}

