function main({ data1 }) {
    // 确保 data1 是一个有效的日期字符串或 Date 对象
    let date = new Date(data1);

    // 检查是否成功创建了 Date 对象
    if (isNaN(date.getTime())) {
        throw new Error("Invalid date format");
    }

    // 增加一天
    date.setDate(date.getDate() + 1);

    // 将结果转换为 ISO 字符串格式
    let result = date.toISOString().split('T')[0];

    return {
        result:result
        }
}

