    { keywords: ['不定时员工日常休假'], name: '不定时员工日常休假' },
    { keywords: ['育儿假'], name: '育儿假' }
  ];

  // 遍历映射表，检查用户输入是否包含任一关键词
  for (const item of holidayMap) {
    if (item.keywords.some(keyword => userChatInput.includes(keyword))) {
      return { result: item.name };
    }
  }

  // 如果都不匹配，返回“没有”
  return { result: '没有' };
}

